import sqlite3


def _channel_exists(conn, channel_id):
    row = conn.execute("SELECT 1 FROM channels WHERE id = ?", (channel_id,)).fetchone()
    return row is not None


def merge_channels_into_archive(source_channel_id: str, target_channel_id: str, db_path: str = "workspace.db") -> dict:
    if source_channel_id == target_channel_id:
        return {"ok": False, "error": "source and target must differ"}
    conn = sqlite3.connect(db_path)
    try:
        if not _channel_exists(conn, source_channel_id):
            return {"ok": False, "error": "source channel not found"}
        if not _channel_exists(conn, target_channel_id):
            return {"ok": False, "error": "target channel not found"}
        cur = conn.execute(
            "UPDATE messages SET channel_id = ? WHERE channel_id = ?",
            (target_channel_id, source_channel_id),
        )
        moved = cur.rowcount
        conn.execute("DELETE FROM pins WHERE channel_id = ?", (source_channel_id,))
        conn.execute("DELETE FROM channel_members WHERE channel_id = ?", (source_channel_id,))
        conn.execute("DELETE FROM channels WHERE id = ?", (source_channel_id,))
        conn.commit()
        return {"ok": True, "messages_moved": moved, "deleted_channel": source_channel_id}
    except sqlite3.Error as exc:
        conn.rollback()
        return {"ok": False, "error": str(exc)}
    finally:
        conn.close()
